/**
 * Lorenz Attractor - Control Loop (self-contained simulation)
 *
 * The entire simulation now lives in this control script: there is no external
 * data generator. loop() advances the Lorenz system, writes x/y/z into the
 * "Lorenz" data table with tableSet(), then dashboardTick() forces the virtual
 * datasets (whose Lua transforms read the table) to render. The UDP source is a
 * dummy, kept only so a connection can be opened; its Lua frame parser just
 * returns {0} and no bytes are ever parsed.
 *
 * This doubles as a control-loop benchmark. The loop free-runs (the worker
 * re-arms it about every millisecond), so STEPS_PER_TICK integration steps run
 * per dashboard refresh; raise it to push raw integration throughput past the
 * refresh rate. Every STATS_EVERY steps the measured step rate is reported, so
 * you can see how fast and how steadily the control loop actually runs.
 *
 * Lorenz system (Edward Lorenz, 1963), classic chaotic parameters:
 *   dx/dt = sigma (y - x),  dy/dt = x (rho - z) - y,  dz/dt = x y - beta z
 * integrated with the Euler method at a fixed dt.
 */

//------------------------------------------------------------------------------
// Configuration & constants
//------------------------------------------------------------------------------

// Lorenz parameters and Euler integration step.
const SIGMA = 10.0;
const RHO   = 28.0;
const BETA  = 8.0 / 3.0;
const DT    = 0.01;

// Integration steps advanced per loop() call. 1 keeps the trace smooth and the
// step rate close to the loop rate; higher values trade refresh rate for raw
// integration throughput.
const STEPS_PER_TICK = 1;

// Report the measured step rate every this many steps (0 disables reporting).
const STATS_EVERY = 50000;

// Data table the virtual datasets read through their transforms.
const TABLE = "Lorenz";

//------------------------------------------------------------------------------
// Mutable state
//------------------------------------------------------------------------------

let x = 0.1, y = 0.0, z = 0.0;
let stepCount = 0;
let lastReportStep = 0;
let lastReportMs = 0;

//------------------------------------------------------------------------------
// Integration
//------------------------------------------------------------------------------

/**
 * @brief Advances the Lorenz state by one Euler step of size DT.
 */
function step() {
  const dx = SIGMA * (y - x);
  const dy = x * (RHO - z) - y;
  const dz = x * y - BETA * z;
  x += dx * DT;
  y += dy * DT;
  z += dz * DT;
}

//------------------------------------------------------------------------------
// Benchmark reporting
//------------------------------------------------------------------------------

/**
 * @brief Reports the measured step rate every STATS_EVERY steps, so the control
 *        loop's speed and steadiness are observable from the dashboard.
 */
function reportRate() {
  if (STATS_EVERY <= 0 || (stepCount - lastReportStep) < STATS_EVERY)
    return;

  const now = Date.now();
  const elapsed = now - lastReportMs;
  if (elapsed > 0) {
    const rate = Math.round((stepCount - lastReportStep) * 1000 / elapsed);
    notifyInfo("Lorenz Attractor", rate + " steps/s");
  }

  lastReportStep = stepCount;
  lastReportMs = now;
}

//------------------------------------------------------------------------------
// Lifecycle
//------------------------------------------------------------------------------

/**
 * @brief Seeds the clock and announces that the simulation runs entirely from
 *        the control loop.
 */
function setup() {
  lastReportMs = Date.now();
  notifyInfo("Lorenz Attractor", "Simulating from the control loop; no external generator.");
}

/**
 * @brief Advances the simulation, publishes x/y/z to the data table, and ticks
 *        the dashboard so the virtual datasets render the fresh trajectory.
 */
function loop() {
  for (let i = 0; i < STEPS_PER_TICK; ++i)
    step();

  stepCount += STEPS_PER_TICK;
  tableSet(TABLE, "x", x);
  tableSet(TABLE, "y", y);
  tableSet(TABLE, "z", z);
  dashboardTick();
  reportRate();
}

